// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockCart = {
  items: [{ id: '1', name: 'Excalibur', price: 999.99 }],
  total: 999.99,
  clearCart: mockClearCart
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCart
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Excalibur', price: 999.99 }];
  });

  // 1. Happy Path
  describe('complete checkout flow', () => {
    it('navigates through all steps to confirmation', async () => {
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-123' });
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Castle Lane');
      await user.type(screen.getByLabelText(/city/i), 'Camelot');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Arthur Pendragon');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/excalibur/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  // 2. Form Validation
  describe('shipping validation', () => {
    it('displays error when ZIP code is invalid', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  // 3. Error States
  describe('payment failure', () => {
    it('displays error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      // ...navigate to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // 4. Loading States
  describe('loading states', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ...navigate to review...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  // 5. Accessibility
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  // 6. Edge Cases
  describe('empty cart', () => {
    it('shows empty cart message and prevents checkout', () => {
      mockCart.items = [];
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});
